-- GENERATED by scripts/build-restore.mjs — do not edit; run `npm run build:restore`.
--
-- Puts the basic database back: clears `public`, then every migration in order
-- (0001_init.sql, 0002_field_options.sql, 0003_whole_price.sql, 0004_product_tag.sql, 0005_facts_and_submission.sql, 0006_notifications.sql, 0007_notify_sweep.sql, 0008_notify_trigger.sql, 0009_status_sync.sql, 0010_push.sql, 0011_field_governance.sql, 0012_consent_records.sql, 0013_order_hold.sql) and the seed.
--
-- One transaction. If any statement fails, nothing changes — read the error,
-- fix, run again. Safe to run more than once.
--
-- Not touched: auth users, storage files, Vault secrets, cron jobs other than
-- ours, Edge Functions and their secrets. See 00-inventory.sql for what is there.

begin;

-- The deferred "published needs a default-language name" checks run at COMMIT,
-- after the seed has written every translation.
set constraints all deferred;


-- ── 1. clear public ──────────────────────────────────────────────────────────
--
-- Object by object, not `drop schema public cascade`. Dropping the schema would
-- also drop Supabase's grants and default privileges on it — the ones that let
-- anon, authenticated and service_role see anything at all — and they would have
-- to be recreated by hand exactly right. Emptying it keeps them.
--
-- Anything that belongs to an extension is left alone: it is the extension's to
-- remove, and Supabase owns most of them.

do $$
declare
  r record;
begin
  for r in
    select c.oid, c.relkind
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public'
       and c.relkind in ('v', 'm', 'r', 'p', 'f', 'S')
       and not exists (select 1 from pg_depend d where d.objid = c.oid and d.deptype = 'e')
     order by case c.relkind when 'v' then 0 when 'm' then 1 when 'S' then 3 else 2 end
  loop
    -- A cascade from an earlier drop may already have taken it.
    continue when not exists (select 1 from pg_class where oid = r.oid);
    execute format(
      'drop %s if exists %s cascade',
      case r.relkind
        when 'v' then 'view'
        when 'm' then 'materialized view'
        when 'S' then 'sequence'
        when 'f' then 'foreign table'
        else 'table'
      end,
      r.oid::regclass
    );
  end loop;

  for r in
    select p.oid
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and not exists (select 1 from pg_depend d where d.objid = p.oid and d.deptype = 'e')
  loop
    continue when not exists (select 1 from pg_proc where oid = r.oid);
    execute format('drop routine if exists %s cascade', r.oid::regprocedure);
  end loop;

  for r in
    select t.oid
      from pg_type t
      join pg_namespace n on n.oid = t.typnamespace
     where n.nspname = 'public'
       and t.typtype in ('e', 'd', 'c', 'r')
       and (t.typrelid = 0 or (select relkind from pg_class where oid = t.typrelid) = 'c')
       and not exists (select 1 from pg_depend d where d.objid = t.oid and d.deptype = 'e')
  loop
    continue when not exists (select 1 from pg_type where oid = r.oid);
    execute format('drop type if exists %s cascade', r.oid::regtype);
  end loop;
end $$;

-- Our two storage policies. The admin one went with public.is_admin(); the read
-- one does not depend on anything in public and would survive, and 0001 would
-- then refuse to create it a second time.
drop policy if exists product_photos_read on storage.objects;
drop policy if exists product_photos_admin on storage.objects;

-- The foreign project's migration history, if it was applied with the CLI. It
-- describes migrations this database no longer contains, and would make any
-- future `supabase db push` from either project refuse to run.
do $$
begin
  if to_regclass('supabase_migrations.schema_migrations') is not null then
    delete from supabase_migrations.schema_migrations;
  end if;
end $$;


-- ════ 0001_init.sql ═════════════════════════════════════════════════════

-- ─────────────────────────────────────────────────────────────────────────────
-- basic — initial schema
--
-- Localised content lives in side tables (`*_translations`), keyed by locale.
-- That was the choice made over localised columns and over one jsonb blob: a
-- fourth language is rows, not a migration and not a rewrite of every query.
--
-- What the side table cannot do is make "English always exists" a column
-- constraint, which localised columns get for free. So it is a trigger instead:
-- a row may be drafted in one language, but it cannot be *published* without a
-- translation in the default locale. See `assert_default_translation`.
-- ─────────────────────────────────────────────────────────────────────────────

create extension if not exists pgcrypto;

-- ── locales ──────────────────────────────────────────────────────────────────
-- A table rather than an enum, because adding a language must be an INSERT.

create table public.locales (
  code      text primary key check (code ~ '^[a-z]{2}(-[A-Za-z0-9]+)*$'),
  label     text not null,
  is_default boolean not null default false,
  position  integer not null default 0
);

-- Exactly one default: the fallback can never be ambiguous or absent.
create unique index locales_one_default on public.locales (is_default) where is_default;

insert into public.locales (code, label, is_default, position) values
  ('sr', 'Srpski',  false, 1),
  ('ru', 'Русский', false, 2),
  ('en', 'English', true,  3);

create or replace function public.default_locale() returns text
  language sql stable as $$
  select code from public.locales where is_default limit 1;
$$;

-- ── shared helpers ───────────────────────────────────────────────────────────

create or replace function public.touch_updated_at() returns trigger
  language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ── products ─────────────────────────────────────────────────────────────────

create type public.product_format as enum ('whole', 'frozen', 'chilled', 'ambient');

create table public.products (
  id                   uuid primary key default gen_random_uuid(),
  slug                 text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  -- Dinars, whole units. Money is never a float.
  price_rsd            integer not null check (price_rsd >= 0),
  -- The owner has not set a real price yet; the site shows it as provisional.
  price_is_placeholder boolean not null default false,
  -- Whether the card offers the piece / whole-cake toggle.
  has_whole            boolean not null default false,
  whole_multiplier     smallint not null default 6 check (whole_multiplier > 0),
  formats              public.product_format[] not null default '{}',
  photo_path           text,
  -- Base64 preview, inlined into the markup so the card never flashes empty.
  photo_blur           text,
  photo_is_placeholder boolean not null default false,
  position             integer not null default 0,
  is_published         boolean not null default false,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

create index products_published_position on public.products (position)
  where is_published;

create trigger products_touch before update on public.products
  for each row execute function public.touch_updated_at();

create table public.product_translations (
  product_id uuid not null references public.products (id) on delete cascade,
  locale     text not null references public.locales (code) on update cascade,
  name       text not null check (length(btrim(name)) > 0),
  note       text not null default '',
  primary key (product_id, locale)
);

-- ── order form configuration ─────────────────────────────────────────────────
-- The set of fields the owner edits in the console. The shape constraint is what
-- keeps a "select with rows: 3" or an "input with no type" out of the table.

create type public.order_field_control as enum ('input', 'select', 'textarea');
create type public.order_field_type    as enum ('text', 'tel', 'email', 'date');

create table public.order_fields (
  id             uuid primary key default gen_random_uuid(),
  key            text not null unique check (key ~ '^[a-z][a-z0-9_]*$'),
  control        public.order_field_control not null,
  input_type     public.order_field_type,
  -- Where a select's options come from; 'cities' is the only source today.
  options_source text,
  rows           smallint check (rows between 2 and 10),
  autocomplete   text,
  is_required    boolean not null default false,
  is_wide        boolean not null default false,
  is_enabled     boolean not null default true,
  position       integer not null default 0,
  constraint order_fields_shape check (
    (control = 'input'    and input_type is not null and rows is null     and options_source is null)
    or (control = 'select'   and input_type is null and rows is null     and options_source is not null)
    or (control = 'textarea' and input_type is null and rows is not null and options_source is null)
  )
);

create table public.order_field_translations (
  field_id    uuid not null references public.order_fields (id) on delete cascade,
  locale      text not null references public.locales (code) on update cascade,
  label       text not null check (length(btrim(label)) > 0),
  placeholder text not null default '',
  help        text not null default '',
  primary key (field_id, locale)
);

-- ── the default-locale invariant ─────────────────────────────────────────────
-- A draft may exist in one language. A *published* row may not: the fallback has
-- to resolve to something for every visitor, whatever their language.

create or replace function public.assert_default_translation() returns trigger
  language plpgsql as $$
declare
  target uuid;
  ok boolean;
begin
  if tg_table_name = 'products' then
    if not new.is_published then return new; end if;
    select exists (
      select 1 from public.product_translations t
      where t.product_id = new.id and t.locale = public.default_locale()
    ) into ok;
    if not ok then
      raise exception 'product % cannot be published without a % translation',
        new.slug, public.default_locale();
    end if;
    return new;
  end if;

  -- order_fields
  if not new.is_enabled then return new; end if;
  select exists (
    select 1 from public.order_field_translations t
    where t.field_id = new.id and t.locale = public.default_locale()
  ) into ok;
  if not ok then
    raise exception 'field % cannot be enabled without a % label',
      new.key, public.default_locale();
  end if;
  return new;
end;
$$;

create constraint trigger products_default_translation
  after insert or update of is_published on public.products
  deferrable initially deferred
  for each row execute function public.assert_default_translation();

create constraint trigger order_fields_default_translation
  after insert or update of is_enabled on public.order_fields
  deferrable initially deferred
  for each row execute function public.assert_default_translation();

-- Deleting the default translation out from under a published row is the same
-- violation from the other side.
create or replace function public.assert_default_translation_kept() returns trigger
  language plpgsql as $$
begin
  if old.locale <> public.default_locale() then return old; end if;

  if tg_table_name = 'product_translations'
     and exists (select 1 from public.products p
                 where p.id = old.product_id and p.is_published) then
    raise exception 'cannot remove the % translation of a published product', old.locale;
  end if;

  if tg_table_name = 'order_field_translations'
     and exists (select 1 from public.order_fields f
                 where f.id = old.field_id and f.is_enabled) then
    raise exception 'cannot remove the % label of an enabled field', old.locale;
  end if;

  return old;
end;
$$;

create trigger product_translations_keep_default
  before delete on public.product_translations
  for each row execute function public.assert_default_translation_kept();

create trigger order_field_translations_keep_default
  before delete on public.order_field_translations
  for each row execute function public.assert_default_translation_kept();

-- ── orders ───────────────────────────────────────────────────────────────────
-- Everything a customer saw is snapshotted. A later price edit or a relabelled
-- field must not silently rewrite an order that has already been placed.

create type public.order_status  as enum ('new', 'confirmed', 'done', 'cancelled');
create type public.order_variant as enum ('piece', 'whole');

create table public.orders (
  id            uuid primary key default gen_random_uuid(),
  created_at    timestamptz not null default now(),
  status        public.order_status not null default 'new',
  -- The language the order was placed in, so replies go back in it.
  locale        text not null references public.locales (code),
  total_rsd     integer not null check (total_rsd >= 0),
  notified_at   timestamptz
);

create index orders_recent on public.orders (created_at desc);

create table public.order_items (
  id             uuid primary key default gen_random_uuid(),
  order_id       uuid not null references public.orders (id) on delete cascade,
  -- Kept null rather than cascading: deleting a product must not delete history.
  product_id     uuid references public.products (id) on delete set null,
  variant        public.order_variant not null,
  qty            integer not null check (qty > 0),
  unit_price_rsd integer not null check (unit_price_rsd >= 0),
  name_snapshot  text not null
);

create index order_items_by_order on public.order_items (order_id);

create table public.order_answers (
  order_id       uuid not null references public.orders (id) on delete cascade,
  field_key      text not null,
  label_snapshot text not null,
  value          text not null,
  position       integer not null default 0,
  primary key (order_id, field_key)
);

-- ── admins ───────────────────────────────────────────────────────────────────
-- Sign-in is a magic link; this table is what turns a signed-in user into an
-- administrator. Revoking access is a delete, not a redeploy.

create table public.admins (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  email      text not null,
  created_at timestamptz not null default now()
);

create or replace function public.is_admin() returns boolean
  language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.admins a where a.user_id = auth.uid());
$$;

-- ── row level security ───────────────────────────────────────────────────────

alter table public.locales                   enable row level security;
alter table public.products                  enable row level security;
alter table public.product_translations      enable row level security;
alter table public.order_fields              enable row level security;
alter table public.order_field_translations  enable row level security;
alter table public.orders                    enable row level security;
alter table public.order_items               enable row level security;
alter table public.order_answers             enable row level security;
alter table public.admins                    enable row level security;

create policy locales_read on public.locales for select using (true);

create policy products_read_published on public.products
  for select using (is_published);
create policy products_admin on public.products
  for all using (public.is_admin()) with check (public.is_admin());

create policy product_translations_read on public.product_translations
  for select using (exists (
    select 1 from public.products p where p.id = product_id and p.is_published
  ));
create policy product_translations_admin on public.product_translations
  for all using (public.is_admin()) with check (public.is_admin());

create policy order_fields_read on public.order_fields
  for select using (is_enabled);
create policy order_fields_admin on public.order_fields
  for all using (public.is_admin()) with check (public.is_admin());

create policy order_field_translations_read on public.order_field_translations
  for select using (exists (
    select 1 from public.order_fields f where f.id = field_id and f.is_enabled
  ));
create policy order_field_translations_admin on public.order_field_translations
  for all using (public.is_admin()) with check (public.is_admin());

-- No anon policy on orders, deliberately. A public INSERT would let anyone post
-- their own `total_rsd`, and a cart the client prices is a cart the client can
-- discount. Submission will land as a security-definer function that recomputes
-- every line from `products` and writes the order itself.
create policy orders_admin on public.orders
  for all using (public.is_admin()) with check (public.is_admin());
create policy order_items_admin on public.order_items
  for all using (public.is_admin()) with check (public.is_admin());
create policy order_answers_admin on public.order_answers
  for all using (public.is_admin()) with check (public.is_admin());

-- An administrator may see the roster; only the service role may change it.
create policy admins_read on public.admins
  for select using (public.is_admin());

-- ── storage ──────────────────────────────────────────────────────────────────

insert into storage.buckets (id, name, public)
  values ('product-photos', 'product-photos', true)
  on conflict (id) do nothing;

create policy product_photos_read on storage.objects
  for select using (bucket_id = 'product-photos');
create policy product_photos_admin on storage.objects
  for all using (bucket_id = 'product-photos' and public.is_admin())
  with check (bucket_id = 'product-photos' and public.is_admin());


-- ════ 0002_field_options.sql ════════════════════════════════════════════

-- ─────────────────────────────────────────────────────────────────────────────
-- A choice field can carry its own list of options.
--
-- Until now `order_fields.options_source` could only point at one hard-coded
-- source ('cities'). A source of 'list' means the options are written by hand —
-- and because the form is translated, they are written per language, which is
-- why they live on the translation row rather than on the field.
--
-- The value stored in an order is the option as it reads in the default locale,
-- matched by position. That is what keeps an answer readable after someone
-- retranslates the list, and it is why the console refuses to save lists of
-- differing lengths: position is the only thing tying the languages together.
-- ─────────────────────────────────────────────────────────────────────────────

alter table public.order_field_translations
  add column if not exists options text[] not null default '{}';

comment on column public.order_field_translations.options is
  'Choice labels in this language, in the same order in every language. The value '
  'recorded in an order is the default-locale label at the matching position.';


-- ════ 0003_whole_price.sql ══════════════════════════════════════════════

-- ── a whole cake is priced, not multiplied ───────────────────────────────────
--
-- `whole_multiplier` was a guess wearing a number. It existed because the summer
-- price sheet has no whole-cake row for either cheesecake, so their whole price
-- was taken as the piece price × 6 — while every cake the sheet *does* price is
-- priced on its own, at a figure that is not a multiple of anything. The owner
-- types that figure in now.
--
-- `price_is_placeholder` goes with it: it marked a price as provisional, no
-- surface ever rendered it, and the honest way to say "no price yet" is to leave
-- the product unpublished.
--
-- Existing rows carry over at exactly what the multiplier implied, so the site
-- shows the same numbers the moment this runs.

alter table public.products
  add column whole_price_rsd integer check (whole_price_rsd >= 0);

update public.products
   set whole_price_rsd = price_rsd * whole_multiplier
 where has_whole;

alter table public.products
  drop column whole_multiplier,
  drop column price_is_placeholder;

-- The toggle and the price are one fact: a card that offers "whole" has to have
-- a number to put on it. Checked here as well as in the console, because the
-- console is not the only thing that will ever write to this table.
alter table public.products
  add constraint products_whole_price
  check (not has_whole or whole_price_rsd is not null);


-- ════ 0004_product_tag.sql ══════════════════════════════════════════════

-- ── the corner tag ───────────────────────────────────────────────────────────
--
-- One short word in the top-left corner of a card: "Hit", "Novo", "Sezonsko".
--
-- Deliberately NOT translated, and deliberately not a table of its own. Every
-- other piece of customer-facing text here has a row per language and the console
-- asks for all three; this one is a word the owner types once and the card shows
-- as typed, in every language. That is a decision, not an oversight: the tags in
-- use are short and read the same in all three, and a dictionary of tags would
-- cost a screen, a join and three inputs to say "Hit".
--
-- Stored trimmed, and never as an empty string — absent is null, so "has a tag"
-- is one test and not two.

alter table public.products
  add column tag text
  check (tag is null or length(btrim(tag)) between 1 and 24);


-- ════ 0005_facts_and_submission.sql ═════════════════════════════════════

-- ── what a card has to be able to say, and how an order gets made ────────────
--
-- Two things, in one migration because they are the same move: the site stops
-- reading a fixture and starts reading this database, and for that it needs both
-- the figures the detail panel shows and a way to send an order back.

-- ── weight and the declaration ───────────────────────────────────────────────
-- Per piece for a piece, per cake for a cake. Macros are per 100g, which is how a
-- declaration states them, and they are nullable: a product with nothing measured
-- yet shows no panel rather than a panel of zeroes.

alter table public.products
  add column weight_g  integer check (weight_g > 0),
  add column kcal      integer check (kcal >= 0),
  add column protein_g numeric(5, 1) check (protein_g >= 0),
  add column fat_g     numeric(5, 1) check (fat_g >= 0),
  add column carbs_g   numeric(5, 1) check (carbs_g >= 0);

-- ── submission ───────────────────────────────────────────────────────────────
--
-- The policy comment in 0001 promised this function, and the promise is the
-- design: there is no anon INSERT on `orders`, so the only way an order comes
-- into being is here, where the server prices it.
--
-- What the client sends is what the client is allowed to know: which product,
-- which variant, how many, and the answers typed into the form. Every dinar is
-- recomputed from `products` — a cart the client prices is a cart the client can
-- discount — and every name and label is snapshotted at this moment, so a later
-- edit in the console cannot rewrite an order that has already been placed.
--
-- Failures are raised with machine-readable codes rather than sentences: the site
-- speaks three languages and the database should not have to.

create or replace function public.submit_order(
  p_locale  text,
  p_items   jsonb,
  p_answers jsonb
) returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_locale   text;
  v_order_id uuid;
  v_total    integer := 0;
  v_item     jsonb;
  v_slug     text;
  v_variant  public.order_variant;
  v_qty      integer;
  v_product  public.products%rowtype;
  v_price    integer;
  v_name     text;
  v_field    record;
  v_value    text;
  v_label    text;
  v_count    integer := 0;
begin
  select code into v_locale from public.locales where code = p_locale;
  if v_locale is null then
    v_locale := public.default_locale();
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'order_empty' using errcode = 'check_violation';
  end if;
  if jsonb_array_length(p_items) > 60 then
    raise exception 'order_too_large' using errcode = 'check_violation';
  end if;

  insert into public.orders (locale, total_rsd) values (v_locale, 0)
  returning id into v_order_id;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_slug := v_item ->> 'slug';
    v_qty  := coalesce((v_item ->> 'qty')::integer, 0);

    if (v_item ->> 'variant') not in ('piece', 'whole') then
      raise exception 'order_bad_variant' using errcode = 'check_violation';
    end if;
    v_variant := (v_item ->> 'variant')::public.order_variant;

    if v_qty < 1 or v_qty > 999 then
      raise exception 'order_bad_quantity' using errcode = 'check_violation';
    end if;

    select * into v_product from public.products
     where slug = v_slug and is_published;
    if not found then
      raise exception 'order_unknown_product:%', v_slug using errcode = 'check_violation';
    end if;

    if v_variant = 'whole' then
      if not v_product.has_whole or v_product.whole_price_rsd is null then
        raise exception 'order_unknown_product:%', v_slug using errcode = 'check_violation';
      end if;
      v_price := v_product.whole_price_rsd;
    else
      v_price := v_product.price_rsd;
    end if;

    -- The name the customer was looking at, in the language they were reading,
    -- falling back exactly the way the site falls back.
    select t.name into v_name from public.product_translations t
     where t.product_id = v_product.id and t.locale = v_locale;
    if v_name is null then
      select t.name into v_name from public.product_translations t
       where t.product_id = v_product.id and t.locale = public.default_locale();
    end if;

    insert into public.order_items
      (order_id, product_id, variant, qty, unit_price_rsd, name_snapshot)
    values
      (v_order_id, v_product.id, v_variant, v_qty, v_price, coalesce(v_name, v_product.slug));

    v_total := v_total + v_price * v_qty;
  end loop;

  -- The form is whatever the console says it is right now: the enabled fields are
  -- the ones asked for, and a required one that came back empty is the reason an
  -- order does not exist rather than something noticed later in a chat.
  for v_field in
    select f.id, f.key, f.is_required, f.position
      from public.order_fields f
     where f.is_enabled
     order by f.position
  loop
    v_value := btrim(coalesce(p_answers ->> v_field.key, ''));

    if v_field.is_required and v_value = '' then
      raise exception 'order_missing_field:%', v_field.key using errcode = 'check_violation';
    end if;
    continue when v_value = '';

    if length(v_value) > 1000 then
      v_value := left(v_value, 1000);
    end if;

    select t.label into v_label from public.order_field_translations t
     where t.field_id = v_field.id and t.locale = v_locale;
    if v_label is null then
      select t.label into v_label from public.order_field_translations t
       where t.field_id = v_field.id and t.locale = public.default_locale();
    end if;

    insert into public.order_answers (order_id, field_key, label_snapshot, value, position)
    values (v_order_id, v_field.key, coalesce(v_label, v_field.key), v_value, v_field.position);

    v_count := v_count + 1;
  end loop;

  update public.orders set total_rsd = v_total where id = v_order_id;

  return v_order_id;
end;
$$;

-- `public` includes every future role; the two that place orders are named.
revoke all on function public.submit_order(text, jsonb, jsonb) from public;
grant execute on function public.submit_order(text, jsonb, jsonb) to anon, authenticated;


-- ════ 0006_notifications.sql ════════════════════════════════════════════

-- ── telling the kitchen an order arrived ─────────────────────────────────────
--
-- The customer is told their request has been sent the moment the row commits.
-- Telling Telegram is a different problem with a different failure mode, so it
-- happens after the fact, from a database webhook, and is retried until it works
-- or until it is loud about not working.
--
-- Everything the retry needs lives in the row: how many times it has been tried,
-- when it was last tried, what went wrong, and — the important one — the Telegram
-- message id, which is also the "already sent" flag. Webhooks fire more than
-- once; two identical orders in a shared staff chat is worse than one arriving a
-- minute late.

-- ── settings ─────────────────────────────────────────────────────────────────
-- Values that have to change without a deploy. The chat id is the reason this
-- table exists: Telegram issues a group a *new* id the moment it is upgraded to
-- a supergroup, which happens by itself, and an env var would mean a redeploy in
-- the middle of an afternoon when orders are arriving.

create table public.settings (
  key        text primary key,
  value      jsonb,
  note       text not null default '',
  updated_at timestamptz not null default now()
);

create trigger settings_touch before update on public.settings
  for each row execute function public.touch_updated_at();

alter table public.settings enable row level security;

-- No anon policy at all: the chat id is not a secret, but nothing on the public
-- site has any business reading configuration. The notifier reaches this with
-- the service role, which RLS does not apply to.
create policy settings_admin on public.settings
  for all using (public.is_admin()) with check (public.is_admin());

insert into public.settings (key, value, note) values
  ('telegram_chat_id', null,
   'The group the notifier posts into, as a JSON number: -1001234567890. Get it by ' ||
   'adding the bot to the group and reading getUpdates — docs/telegram-setup.md has ' ||
   'the steps. The notifier rewrites this by itself if the group is upgraded to a ' ||
   'supergroup and Telegram hands back a new id.'),
  ('shop_timezone', '"Europe/Belgrade"',
   'The zone order times are written in. Staff read these at a counter in Belgrade, ' ||
   'not in UTC.'),
  ('notify_endpoint', null,
   'The notify-order function, as a JSON string: ' ||
   '"https://<project>.supabase.co/functions/v1/notify-order". Only the retry sweep ' ||
   'uses it — the webhook has its own copy of the URL. Left null, the sweep does ' ||
   'nothing and says so.')
on conflict (key) do nothing;

-- ── what an order remembers about being announced ────────────────────────────

alter table public.orders
  -- Something a person can say out loud. A uuid is not a number you read down
  -- the phone to a café that called to change their order.
  add column number              integer generated always as identity,
  add column notify_attempts     integer not null default 0,
  add column notify_attempted_at timestamptz,
  add column notify_error        text,
  -- Set exactly once, by whichever delivery wins. Its presence is what makes a
  -- second webhook a no-op.
  add column telegram_message_id bigint;

create unique index orders_number on public.orders (number);

-- The sweep's whole query: the orders that have not been announced. Partial, so
-- it stays the size of the backlog rather than the size of the history.
create index orders_unannounced on public.orders (created_at)
  where notified_at is null;

/**
 * Claiming an order for delivery.
 *
 * Two webhook deliveries can arrive at the same instant, and a read-then-check
 * would let both of them decide the message had not been sent yet. This is one
 * statement: the row is claimed and counted in the same update, and a claim that
 * comes back empty means someone else already has it — or it is already sent.
 *
 * The attempt is counted here, at the start, rather than on failure. A function
 * that dies mid-flight still has to be seen to have tried, or the sweep will
 * spin on it forever.
 */
create or replace function public.claim_order_notification(p_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = public
as $$
declare
  v_order public.orders;
begin
  update public.orders
     set notify_attempts     = notify_attempts + 1,
         notify_attempted_at = now()
   where id = p_id
     and telegram_message_id is null
  returning * into v_order;

  return v_order;
end;
$$;

revoke all on function public.claim_order_notification(uuid) from public;
grant execute on function public.claim_order_notification(uuid) to service_role;

/**
 * The other end of a delivery.
 *
 * Success and failure are one function so the notifier cannot write half of
 * either: an order is never left holding a message id with no timestamp, or an
 * error that a later success forgot to clear.
 */
create or replace function public.record_order_notification(
  p_id         uuid,
  p_message_id bigint,
  p_error      text
) returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_message_id is not null then
    update public.orders
       set telegram_message_id = p_message_id,
           notified_at         = now(),
           notify_error        = null
     where id = p_id;
  else
    update public.orders
       set notify_error = left(coalesce(p_error, 'unknown'), 500)
     where id = p_id;
  end if;
end;
$$;

revoke all on function public.record_order_notification(uuid, bigint, text) from public;
grant execute on function public.record_order_notification(uuid, bigint, text) to service_role;

-- ── the ones that got stuck ──────────────────────────────────────────────────
-- Orders past the attempt limit stop being retried, which is not the same as
-- being fine. This is where to look; docs/telegram-setup.md says so too.

create or replace view public.orders_awaiting_notification
with (security_invoker = true) as
  select o.number,
         o.id,
         o.created_at,
         o.locale,
         o.total_rsd,
         o.notify_attempts,
         o.notify_attempted_at,
         o.notify_error,
         o.notify_attempts >= 10 as gave_up
    from public.orders o
   where o.notified_at is null
   order by o.created_at;


-- ════ 0007_notify_sweep.sql ═════════════════════════════════════════════

-- ── the retry sweep ──────────────────────────────────────────────────────────
--
-- A database webhook fires once. If the function was cold and timed out, if
-- Telegram was down for ninety seconds, if the bot was rate-limited — that is the
-- end of it, and the order sits in the table unannounced while the shop believes
-- it has been told. So something has to come back and look.
--
-- pg_cron and pg_net rather than a scheduled Edge Function, deliberately:
--
--  * The thing being swept is a query over rows in this database. A scheduled
--    function would have to ask the database the same question over HTTP, with a
--    service key, from another deployment artifact that has to be kept in step
--    with this schema. The cron job *is* the query.
--  * The backoff is a predicate — `notify_attempted_at < now() - <interval>` —
--    and it belongs where the columns are.
--  * One fewer secret in one fewer place.
--
-- The cost is honest: two extensions, and a schedule that lives in the database
-- rather than in the repository. `cron.job` is where it can be read back.

create extension if not exists pg_cron;
create extension if not exists pg_net;

/**
 * Re-announce whatever has not been announced.
 *
 * Deliberately conservative about what it picks up:
 *   · older than two minutes — the webhook gets first refusal, and a sweep that
 *     raced it would be the duplicate it is supposed to prevent;
 *   · under ten attempts — past that something is wrong that retrying will not
 *     fix, and the row stays in `orders_awaiting_notification` to be found;
 *   · backed off by attempt count — one minute, then two, four, eight, up to an
 *     hour, so a broken token is not a hundred requests an hour forever;
 *   · twenty at a time — a sweep is not a way to discover Telegram's flood limit.
 *
 * `net.http_post` returns immediately with a request id; the response lands in
 * `net._http_response` later. That is the point: the sweep is not waiting on
 * Telegram either. Whether a given attempt worked is read off the order, not off
 * the HTTP reply.
 */
create or replace function public.sweep_order_notifications()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_endpoint text;
  v_secret   text;
  v_order    record;
  v_sent     integer := 0;
begin
  select value #>> '{}' into v_endpoint from public.settings where key = 'notify_endpoint';
  if v_endpoint is null or v_endpoint = '' then
    raise log 'sweep_order_notifications: settings.notify_endpoint is not set, nothing swept';
    return 0;
  end if;

  -- The same shared secret the webhook sends. In Vault rather than in `settings`,
  -- because `settings` is readable by every administrator and this is the one
  -- value that decides whether a request is genuinely from us.
  select decrypted_secret into v_secret
    from vault.decrypted_secrets
   where name = 'notify_webhook_secret';

  if v_secret is null then
    raise log 'sweep_order_notifications: vault secret notify_webhook_secret is missing';
    return 0;
  end if;

  for v_order in
    select o.id, o.notify_attempts
      from public.orders o
     where o.notified_at is null
       and o.telegram_message_id is null
       and o.created_at < now() - interval '2 minutes'
       and o.notify_attempts < 10
       and (
         o.notify_attempted_at is null
         or o.notify_attempted_at <
            now() - least(interval '1 hour',
                          interval '1 minute' * power(2, o.notify_attempts))
       )
     order by o.created_at
     limit 20
  loop
    perform net.http_post(
      url     := v_endpoint,
      headers := jsonb_build_object(
                   'content-type', 'application/json',
                   'x-notify-secret', v_secret
                 ),
      body    := jsonb_build_object(
                   'type', 'SWEEP',
                   'table', 'orders',
                   'record', jsonb_build_object('id', v_order.id)
                 ),
      timeout_milliseconds := 15000
    );

    v_sent := v_sent + 1;
  end loop;

  if v_sent > 0 then
    raise log 'sweep_order_notifications: re-invoked % order(s)', v_sent;
  end if;

  return v_sent;
end;
$$;

revoke all on function public.sweep_order_notifications() from public;

-- Every two minutes. With the two-minute floor above, a webhook that silently
-- did nothing costs a customer four minutes of the shop not knowing — and a
-- shop that is closed at 03:00 loses nothing by the sweep running anyway.
select cron.schedule(
  'sweep-order-notifications',
  '*/2 * * * *',
  $$select public.sweep_order_notifications();$$
);


-- ════ 0008_notify_trigger.sql ═══════════════════════════════════════════

-- ── the webhook, as a migration ──────────────────────────────────────────────
--
-- A Supabase "Database Webhook" is a trigger that calls pg_net. This is that
-- trigger, written out, for three reasons:
--
--  * It lives in the repository. A webhook made by clicking through the
--    dashboard is configuration nobody can review, diff or recreate on a second
--    project without remembering the clicks.
--  * It reads the endpoint and the secret from the same two places the retry
--    sweep does — `settings.notify_endpoint` and the Vault secret
--    `notify_webhook_secret` — so the two cannot drift apart. The dashboard
--    version holds its own copy of both.
--  * The dashboard moves the feature around between releases; SQL does not.
--
-- If you already created a webhook in the dashboard as well, delete one of the
-- two. Nothing would be sent twice — `claim_order_notification` sees to that —
-- but every order would wake the function twice for no reason.

/**
 * Wake the notifier for a new order.
 *
 * The one rule here outranks all the others: this must never make the insert
 * fail. A customer's order that could not be written because Telegram was not
 * configured yet is the worst possible outcome of a notification system, so
 * every failure is logged and swallowed, and the sweep picks the order up once
 * whatever was missing is in place.
 *
 * `net.http_post` only queues the request. The queue is a table, the insert into
 * it belongs to this transaction, and the background worker cannot see it until
 * the transaction commits — so the function is never woken for an order that
 * then rolls back, and by the time it runs the items and answers `submit_order`
 * writes after this row are there too.
 */
create or replace function public.notify_order_inserted()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_endpoint text;
  v_secret   text;
begin
  select value #>> '{}' into v_endpoint from public.settings where key = 'notify_endpoint';
  select decrypted_secret into v_secret
    from vault.decrypted_secrets
   where name = 'notify_webhook_secret';

  if v_endpoint is null or v_endpoint = '' or v_secret is null then
    raise log 'notify_order_inserted: endpoint or secret not configured, order % left for the sweep', new.id;
    return new;
  end if;

  perform net.http_post(
    url     := v_endpoint,
    headers := jsonb_build_object(
                 'content-type', 'application/json',
                 'x-notify-secret', v_secret
               ),
    body    := jsonb_build_object(
                 'type', 'INSERT',
                 'table', 'orders',
                 'record', jsonb_build_object('id', new.id)
               ),
    timeout_milliseconds := 5000
  );

  return new;
exception
  when others then
    raise log 'notify_order_inserted: % (order %), left for the sweep', sqlerrm, new.id;
    return new;
end;
$$;

revoke all on function public.notify_order_inserted() from public;

drop trigger if exists orders_notify on public.orders;

create trigger orders_notify
  after insert on public.orders
  for each row execute function public.notify_order_inserted();


-- ════ 0009_status_sync.sql ══════════════════════════════════════════════

-- ── statuses, in the shop's words, and the staff chat kept in step ──────────
--
-- The console had new / confirmed / done / cancelled. The shop says new /
-- processing / completed / canceled, and a status is a word staff read forty
-- times a day, so the enum is renamed rather than relabelled in three places.
-- `rename value` rewrites no rows: existing orders keep their status, under its
-- new name.

alter type public.order_status rename value 'confirmed' to 'processing';
alter type public.order_status rename value 'done'      to 'completed';
alter type public.order_status rename value 'cancelled' to 'canceled';

-- ── what the Telegram message currently says ─────────────────────────────────
--
-- When a status changes in the console, the order's message in the staff chat is
-- edited to say so — one card per order that is always true, rather than a
-- stream of "order 42 is now completed" replies burying the next order.
--
--  · telegram_chat_id — the chat the message actually lives in. The chat id in
--    `settings` can change (a group upgraded to a supergroup gets a new one);
--    an edit has to go where the message is, not where new ones go.
--  · telegram_status — the status the message shows. Different from `status`
--    means the edit has not landed yet, which is also what the sweep looks for.
--  · status_changed_at — when the console last changed it, so the sweep retries
--    a failed edit for a day and then stops, rather than forever.

alter table public.orders
  add column telegram_chat_id  bigint,
  add column telegram_status   public.order_status,
  add column status_changed_at timestamptz;

-- The old three-argument version is replaced, not overloaded: with a default on
-- the fourth argument, both would match a three-argument call and Postgres would
-- refuse to choose.
drop function if exists public.record_order_notification(uuid, bigint, text);

/**
 * The outcome of a delivery or an edit, written in one statement.
 *
 * `p_status` is the status the message was rendered with — not whatever the row
 * says now. If a colleague changed it between the render and this write, the two
 * differ, and the sweep sends the edit that closes the gap.
 */
create or replace function public.record_order_notification(
  p_id         uuid,
  p_message_id bigint,
  p_error      text,
  p_status     public.order_status default null,
  p_chat_id    bigint default null
) returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_message_id is not null then
    update public.orders
       set telegram_message_id = p_message_id,
           telegram_chat_id    = coalesce(p_chat_id, telegram_chat_id),
           telegram_status     = coalesce(p_status, telegram_status),
           notified_at         = coalesce(notified_at, now()),
           notify_error        = null
     where id = p_id;
  else
    update public.orders
       set notify_error = left(coalesce(p_error, 'unknown'), 500)
     where id = p_id;
  end if;
end;
$$;

revoke all on function public.record_order_notification(uuid, bigint, text, public.order_status, bigint) from public;
grant execute on function public.record_order_notification(uuid, bigint, text, public.order_status, bigint) to service_role;

/** Stamp the change, so the sweep knows how recent an unsynced status is. */
create or replace function public.stamp_status_change()
returns trigger
language plpgsql
as $$
begin
  if new.status is distinct from old.status then
    new.status_changed_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists orders_stamp_status on public.orders;
create trigger orders_stamp_status
  before update of status on public.orders
  for each row execute function public.stamp_status_change();

/**
 * Ask the notifier to edit the message.
 *
 * Only once there is a message: an order whose announcement has not gone out
 * yet will be announced with whatever its status is by then, so there is
 * nothing to edit. Like the insert trigger, this never fails the update — a
 * status change in the console must not be refused because Telegram is not
 * configured.
 */
create or replace function public.notify_order_status()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_endpoint text;
  v_secret   text;
begin
  if new.status is not distinct from old.status or new.telegram_message_id is null then
    return new;
  end if;

  select value #>> '{}' into v_endpoint from public.settings where key = 'notify_endpoint';
  select decrypted_secret into v_secret
    from vault.decrypted_secrets
   where name = 'notify_webhook_secret';

  if v_endpoint is null or v_endpoint = '' or v_secret is null then
    return new;
  end if;

  perform net.http_post(
    url     := v_endpoint,
    headers := jsonb_build_object(
                 'content-type', 'application/json',
                 'x-notify-secret', v_secret
               ),
    body    := jsonb_build_object(
                 'type', 'STATUS',
                 'table', 'orders',
                 'record', jsonb_build_object('id', new.id)
               ),
    timeout_milliseconds := 5000
  );

  return new;
exception
  when others then
    raise log 'notify_order_status: % (order %), left for the sweep', sqlerrm, new.id;
    return new;
end;
$$;

revoke all on function public.notify_order_status() from public;

drop trigger if exists orders_notify_status on public.orders;
create trigger orders_notify_status
  after update of status on public.orders
  for each row execute function public.notify_order_status();

-- ── the sweep learns about edits ─────────────────────────────────────────────
-- Same function, second loop: messages that exist but show a stale status,
-- changed in the last day and more than a minute ago (the trigger gets first
-- refusal, as with new orders).

create or replace function public.sweep_order_notifications()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_endpoint text;
  v_secret   text;
  v_order    record;
  v_sent     integer := 0;
begin
  select value #>> '{}' into v_endpoint from public.settings where key = 'notify_endpoint';
  if v_endpoint is null or v_endpoint = '' then
    raise log 'sweep_order_notifications: settings.notify_endpoint is not set, nothing swept';
    return 0;
  end if;

  select decrypted_secret into v_secret
    from vault.decrypted_secrets
   where name = 'notify_webhook_secret';

  if v_secret is null then
    raise log 'sweep_order_notifications: vault secret notify_webhook_secret is missing';
    return 0;
  end if;

  -- New orders nobody has been told about.
  for v_order in
    select o.id
      from public.orders o
     where o.notified_at is null
       and o.telegram_message_id is null
       and o.created_at < now() - interval '2 minutes'
       and o.notify_attempts < 10
       and (
         o.notify_attempted_at is null
         or o.notify_attempted_at <
            now() - least(interval '1 hour',
                          interval '1 minute' * power(2, o.notify_attempts))
       )
     order by o.created_at
     limit 20
  loop
    perform net.http_post(
      url     := v_endpoint,
      headers := jsonb_build_object('content-type', 'application/json',
                                    'x-notify-secret', v_secret),
      body    := jsonb_build_object('type', 'SWEEP', 'table', 'orders',
                                    'record', jsonb_build_object('id', v_order.id)),
      timeout_milliseconds := 15000
    );
    v_sent := v_sent + 1;
  end loop;

  -- Messages showing a status the console has since changed.
  for v_order in
    select o.id
      from public.orders o
     where o.telegram_message_id is not null
       and o.telegram_status is distinct from o.status
       and o.status_changed_at > now() - interval '1 day'
       and o.status_changed_at < now() - interval '1 minute'
     order by o.status_changed_at
     limit 20
  loop
    perform net.http_post(
      url     := v_endpoint,
      headers := jsonb_build_object('content-type', 'application/json',
                                    'x-notify-secret', v_secret),
      body    := jsonb_build_object('type', 'STATUS', 'table', 'orders',
                                    'record', jsonb_build_object('id', v_order.id)),
      timeout_milliseconds := 15000
    );
    v_sent := v_sent + 1;
  end loop;

  if v_sent > 0 then
    raise log 'sweep_order_notifications: re-invoked % order(s)', v_sent;
  end if;

  return v_sent;
end;
$$;

revoke all on function public.sweep_order_notifications() from public;


-- ════ 0010_push.sql ═════════════════════════════════════════════════════

-- ── push notifications to the people running the console ─────────────────────
--
-- Telegram is the shared room. Push is the phone in someone's pocket: the same
-- new order, on the lock screen of each administrator who asked for it, whether
-- or not the group chat is muted.
--
-- A subscription is a browser's promise to wake up for us: an endpoint on the
-- browser vendor's push service, and two keys only that browser can use to read
-- what we send. One row per device, owned by the administrator who enabled it.

create table public.push_subscriptions (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users (id) on delete cascade,
  -- Unique: the same browser subscribing twice is the same subscription.
  endpoint        text not null unique,
  p256dh          text not null,
  auth            text not null,
  -- "Safari on iPhone", written by the browser when it subscribes, so the list
  -- of devices means something to the person reading it.
  label           text not null default '',
  created_at      timestamptz not null default now(),
  last_success_at timestamptz,
  last_error      text,
  failures        integer not null default 0
);

create index push_subscriptions_by_user on public.push_subscriptions (user_id);

alter table public.push_subscriptions enable row level security;

-- Your own devices, and only while you are an administrator. Nobody manages
-- anyone else's phone from the console; revoking someone's access stops their
-- pushes because the notifier only sends to current administrators.
create policy push_subscriptions_own on public.push_subscriptions
  for all
  using (user_id = auth.uid() and public.is_admin())
  with check (user_id = auth.uid() and public.is_admin());

-- ── sent once ────────────────────────────────────────────────────────────────
-- The Telegram delivery is retried until it works; a push is not. A push that
-- arrives twelve minutes late, or twice, is worse than one that does not arrive
-- — so it is claimed exactly once, before it is sent, and never again.

alter table public.orders add column push_sent_at timestamptz;

create or replace function public.claim_order_push(p_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_claimed uuid;
begin
  update public.orders
     set push_sent_at = now()
   where id = p_id
     and push_sent_at is null
  returning id into v_claimed;

  return v_claimed is not null;
end;
$$;

revoke all on function public.claim_order_push(uuid) from public;
grant execute on function public.claim_order_push(uuid) to service_role;

-- ── the public half of the key pair ──────────────────────────────────────────
-- Browsers need the server's public key to subscribe; it is public by design.
-- Kept here rather than in an environment variable so setting up push is one
-- SQL statement and a function secret, not a redeploy of the site. The private
-- half lives only in the notify-order function's secrets.

insert into public.settings (key, value, note) values
  ('vapid_public_key', null,
   'The Web Push public key, as a JSON string. Generate the pair with ' ||
   '`npm run vapid`; the private half goes into the notify-order function as ' ||
   'VAPID_PRIVATE_KEY. docs/push-setup.md has the steps.')
on conflict (key) do nothing;


-- ════ 0011_field_governance.sql ═════════════════════════════════════════

-- ════ 0011 — order form governance ══════════════════════════════════════════
--
-- The privacy policy now promises what the order form may contain. This makes
-- the database keep that promise rather than the console's good manners:
--
--   · every field states its purpose, per language (shown in Annex 1)
--   · a field is `normal` or `special_category`; special ones are never required
--   · every change to the field set is written to an audit table
--   · answers typed into the form are cleared after the retention period
--
-- The "no card / IBAN / ID number fields" rule lives in the console
-- (src/lib/order/governance.ts) — it is a keyword match, and keywords in three
-- languages are easier to keep in one TypeScript constant than in SQL.

-- ── purpose and sensitivity ─────────────────────────────────────────────────

create type public.order_field_sensitivity as enum ('normal', 'special_category');

alter table public.order_fields
  add column sensitivity public.order_field_sensitivity not null default 'normal',
  add constraint order_fields_special_optional
    check (sensitivity = 'normal' or not is_required);

alter table public.order_field_translations
  add column purpose text not null default '';

-- An enabled field must say why it is asked, at least in the default language.
create or replace function public.assert_field_purpose() returns trigger
  language plpgsql as $$
declare
  v_field uuid;
begin
  -- Branch before touching columns: a record only has its own table's fields.
  if tg_table_name = 'order_fields' then
    if not new.is_enabled then
      return null;
    end if;
    v_field := new.id;
  else
    v_field := new.field_id;
  end if;
  if exists (select 1 from public.order_fields f where f.id = v_field and f.is_enabled)
     and not exists (
       select 1 from public.order_field_translations t
        where t.field_id = v_field
          and t.locale = public.default_locale()
          and length(btrim(t.purpose)) > 0
     ) then
    raise exception 'order_field_needs_purpose' using errcode = 'check_violation';
  end if;
  return null;
end;
$$;

-- The shipped fields, so the constraint triggers below hold from the start.
update public.order_field_translations t
   set purpose = p.purpose
  from public.order_fields f,
       (values
         ('venue', 'en', 'Identify the venue placing the order and address the invoice.'),
         ('venue', 'ru', 'Определить заведение, от имени которого сделан заказ, и выставить счёт.'),
         ('venue', 'sr', 'Identifikacija lokala koji poručuje i izdavanje računa.'),
         ('contact', 'en', 'Know whom to speak to about the order.'),
         ('contact', 'ru', 'Знать, с кем связаться по заказу.'),
         ('contact', 'sr', 'Da znamo s kim da razgovaramo o porudžbini.'),
         ('phone', 'en', 'Confirm the order and arrange delivery.'),
         ('phone', 'ru', 'Подтвердить заказ и согласовать доставку.'),
         ('phone', 'sr', 'Potvrda porudžbine i dogovor o dostavi.'),
         ('email', 'en', 'Send the invoice or order information by e-mail, if you want it.'),
         ('email', 'ru', 'Отправить счёт или информацию о заказе по почте, если вы этого хотите.'),
         ('email', 'sr', 'Slanje računa ili informacija o porudžbini e-poštom, ako to želite.'),
         ('city', 'en', 'Plan the delivery and apply the terms for your city.'),
         ('city', 'ru', 'Спланировать доставку и применить условия для вашего города.'),
         ('city', 'sr', 'Planiranje dostave i primena uslova za vaš grad.'),
         ('date', 'en', 'Schedule production and delivery.'),
         ('date', 'ru', 'Запланировать приготовление и доставку.'),
         ('date', 'sr', 'Planiranje pripreme i dostave.'),
         ('comment', 'en', 'Take delivery, packing and kitchen notes into account.'),
         ('comment', 'ru', 'Учесть пожелания по доставке, упаковке и для кухни.'),
         ('comment', 'sr', 'Uvažavanje napomena o dostavi, pakovanju i za kuhinju.')
       ) as p(key, locale, purpose)
 where f.id = t.field_id and f.key = p.key and t.locale = p.locale;

-- Fields added by hand before this migration get a stand-in, so enabling the
-- trigger cannot fail; the console shows it and the owner replaces it.
update public.order_field_translations
   set purpose = 'Processing your order request.'
 where purpose = '' and locale = public.default_locale();

create constraint trigger order_fields_purpose
  after insert or update of is_enabled on public.order_fields
  deferrable initially deferred
  for each row execute function public.assert_field_purpose();

create constraint trigger order_field_translations_purpose
  after insert or update of purpose on public.order_field_translations
  deferrable initially deferred
  for each row execute function public.assert_field_purpose();

-- ── audit ───────────────────────────────────────────────────────────────────

create table public.order_field_audit (
  id         bigint generated always as identity primary key,
  at         timestamptz not null default now(),
  actor      uuid default auth.uid(),
  actor_email text,
  table_name text not null,
  action     text not null check (action in ('INSERT', 'UPDATE', 'DELETE')),
  field_id   uuid,
  before     jsonb,
  after      jsonb
);

create index order_field_audit_recent on public.order_field_audit (at desc);

alter table public.order_field_audit enable row level security;
-- Read by administrators; written only by the trigger below, never by a client.
create policy order_field_audit_read on public.order_field_audit
  for select using (public.is_admin());

create or replace function public.audit_order_fields() returns trigger
  language plpgsql security definer set search_path = public as $$
declare
  v_before jsonb := case when tg_op = 'INSERT' then null else to_jsonb(old) end;
  v_after  jsonb := case when tg_op = 'DELETE' then null else to_jsonb(new) end;
begin
  -- A save that changes nothing is not a change to the field set.
  if tg_op = 'UPDATE' and v_before = v_after then
    return null;
  end if;
  insert into public.order_field_audit (actor, actor_email, table_name, action, field_id, before, after)
  values (
    auth.uid(),
    (select email from auth.users where id = auth.uid()),
    tg_table_name,
    tg_op,
    coalesce(v_after ->> 'field_id', v_after ->> 'id', v_before ->> 'field_id', v_before ->> 'id')::uuid,
    v_before,
    v_after
  );
  return null;
end;
$$;

create trigger order_fields_audit
  after insert or update or delete on public.order_fields
  for each row execute function public.audit_order_fields();

create trigger order_field_translations_audit
  after insert or update or delete on public.order_field_translations
  for each row execute function public.audit_order_fields();

-- When the published field set last changed — the "as of" date of Annex 1.
-- Public, and it reveals a date and nothing else.
create or replace function public.order_form_changed_at() returns timestamptz
  language sql stable security definer set search_path = public as $$
  select max(at) from public.order_field_audit;
$$;
revoke all on function public.order_form_changed_at() from public;
grant execute on function public.order_form_changed_at() to anon, authenticated;

-- ── retention ───────────────────────────────────────────────────────────────

-- THE retention period. One place; the policy text and docs/privacy-cookies.md
-- refer to it.
create or replace function public.order_answers_retention() returns interval
  language sql immutable as $$ select interval '24 months' $$;

-- Answers kept past the period because they are invoice data — the venue is who
-- the invoice was made out to. Everything else typed into the form goes.
create or replace function public.order_answers_kept_for_invoices() returns text[]
  language sql immutable as $$ select array['venue']::text[] $$;

alter table public.orders add column answers_cleared_at timestamptz;

create or replace function public.purge_old_order_answers() returns integer
  language plpgsql security definer set search_path = public as $$
declare
  v_count integer;
begin
  with old as (
    select id from public.orders
     where created_at < now() - public.order_answers_retention()
       and answers_cleared_at is null
  ), gone as (
    delete from public.order_answers a
     using old
     where a.order_id = old.id
       and a.field_key <> all (public.order_answers_kept_for_invoices())
    returning 1
  )
  select count(*) into v_count from gone;

  -- Items, totals and the kept answers stay; the order is marked so the next run
  -- skips it.
  update public.orders set answers_cleared_at = now()
   where created_at < now() - public.order_answers_retention()
     and answers_cleared_at is null;

  return v_count;
end;
$$;
revoke all on function public.purge_old_order_answers() from public;

-- Daily, at a quiet hour (UTC).
select cron.schedule('purge-old-order-answers', '17 3 * * *', 'select public.purge_old_order_answers()');


-- ════ 0012_consent_records.sql ══════════════════════════════════════════

-- ════ 0012 — cookie consent log ═════════════════════════════════════════════
--
-- One row per decision made in the cookie banner or settings dialog: the proof
-- of what was agreed to, when, against which policy and UI. Anonymous — a random
-- per-browser id, no IP, no user agent.
--
-- The public role may insert and nothing else: it cannot read back anyone's
-- choices, its own included. Administrators can read.

create table public.consent_records (
  id             bigint generated always as identity primary key,
  consent_id     uuid not null,
  decided_at     timestamptz not null,
  received_at    timestamptz not null default now(),
  analytics      boolean not null,
  marketing      boolean not null,
  policy_version text not null check (length(policy_version) <= 32),
  ui_version     text not null check (length(ui_version) <= 16),
  locale         text not null references public.locales (code),
  schema         text not null check (length(schema) <= 500)
);

create index consent_records_by_id on public.consent_records (consent_id, decided_at desc);

alter table public.consent_records enable row level security;

create policy consent_records_insert on public.consent_records
  for insert to anon, authenticated
  -- A decision dated far from now is not a decision made just now.
  with check (decided_at between now() - interval '1 day' and now() + interval '1 day');

create policy consent_records_admin_read on public.consent_records
  for select using (public.is_admin());

grant insert on public.consent_records to anon, authenticated;


-- ════ 0013_order_hold.sql ═══════════════════════════════════════════════

-- ════ 0013 — a minute to change your mind ═══════════════════════════════════
--
-- A submitted order is written at once, then held for 60 seconds. In that
-- minute the customer can take it back ("made a mistake? fix it") with the
-- token only they were given; after it, it is released to the shop — Telegram,
-- push — by pg_cron, so it does not matter whether the tab is still open.
--
-- Nothing about `submit_order` changes: the hold is two column defaults, and
-- the release is a job. The notifiers learn one rule — a held order is not
-- theirs yet.

alter table public.orders
  add column release_at   timestamptz default now() + interval '60 seconds',
  add column released_at  timestamptz,
  add column cancel_token uuid default gen_random_uuid();

-- Everything already in the table was never held.
update public.orders set release_at = created_at, released_at = created_at, cancel_token = null;

create index orders_held on public.orders (release_at) where released_at is null;

/** Is this order still in its minute? */
create or replace function public.order_is_held(p_order public.orders) returns boolean
  language sql stable as $$
  select p_order.released_at is null and p_order.release_at > now()
$$;

-- ── submission, with the token ──────────────────────────────────────────────

create or replace function public.submit_order_held(
  p_locale  text,
  p_items   jsonb,
  p_answers jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid := public.submit_order(p_locale, p_items, p_answers);
  v_order public.orders;
begin
  select * into v_order from public.orders where id = v_id;
  return jsonb_build_object(
    'id', v_order.id,
    'token', v_order.cancel_token,
    'release_at', v_order.release_at
  );
end;
$$;
revoke all on function public.submit_order_held(text, jsonb, jsonb) from public;
grant execute on function public.submit_order_held(text, jsonb, jsonb) to anon, authenticated;

-- ── taking it back ──────────────────────────────────────────────────────────

-- Deleted, not marked cancelled: the shop never saw it, so there is nothing for
-- the console to show. Only within the minute, only with the token.
create or replace function public.cancel_held_order(p_id uuid, p_token uuid) returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_gone uuid;
begin
  delete from public.orders
   where id = p_id
     and cancel_token = p_token
     and released_at is null
     and release_at > now()
  returning id into v_gone;
  return v_gone is not null;
end;
$$;
revoke all on function public.cancel_held_order(uuid, uuid) from public;
grant execute on function public.cancel_held_order(uuid, uuid) to anon, authenticated;

-- ── notifying: one sender, and no sending while held ────────────────────────

create or replace function public.post_order_inserted(p_id uuid) returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_endpoint text;
  v_secret   text;
begin
  select value #>> '{}' into v_endpoint from public.settings where key = 'notify_endpoint';
  select decrypted_secret into v_secret
    from vault.decrypted_secrets
   where name = 'notify_webhook_secret';

  if v_endpoint is null or v_endpoint = '' or v_secret is null then
    raise log 'post_order_inserted: endpoint or secret not configured, order % left for the sweep', p_id;
    return;
  end if;

  perform net.http_post(
    url     := v_endpoint,
    headers := jsonb_build_object('content-type', 'application/json', 'x-notify-secret', v_secret),
    body    := jsonb_build_object('type', 'INSERT', 'table', 'orders',
                                  'record', jsonb_build_object('id', p_id)),
    timeout_milliseconds := 5000
  );
exception
  when others then
    raise log 'post_order_inserted: % (order %), left for the sweep', sqlerrm, p_id;
end;
$$;
revoke all on function public.post_order_inserted(uuid) from public;

-- The insert trigger: a held order waits for the release job instead.
create or replace function public.notify_order_inserted()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.order_is_held(new) then
    perform public.post_order_inserted(new.id);
  end if;
  return new;
end;
$$;

-- The notifiers claim before they send; a held order cannot be claimed, so the
-- 2-minute sweep cannot leak one early either.
create or replace function public.claim_order_notification(p_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = public
as $$
declare
  v_order public.orders;
begin
  update public.orders o
     set notify_attempts     = notify_attempts + 1,
         notify_attempted_at = now()
   where o.id = p_id
     and o.telegram_message_id is null
     and not public.order_is_held(o)
  returning * into v_order;

  return v_order;
end;
$$;

create or replace function public.claim_order_push(p_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_claimed uuid;
begin
  update public.orders o
     set push_sent_at = now()
   where o.id = p_id
     and o.push_sent_at is null
     and not public.order_is_held(o)
  returning id into v_claimed;

  return v_claimed is not null;
end;
$$;

-- ── release ─────────────────────────────────────────────────────────────────

create or replace function public.release_held_orders() returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id    uuid;
  v_count integer := 0;
begin
  for v_id in
    update public.orders
       set released_at = now(),
           cancel_token = null
     where released_at is null
       and release_at <= now()
    returning id
  loop
    perform public.post_order_inserted(v_id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;
revoke all on function public.release_held_orders() from public;

-- Every 10 seconds: an order reaches the shop 60–70 s after it was sent.
select cron.schedule('release-held-orders', '10 seconds', 'select public.release_held_orders()');


